package com.clinic.notification.service;
import com.clinic.notification.domain.*;import com.clinic.notification.dto.NotificationDtos.EventRequest;import com.clinic.notification.repository.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.data.domain.PageRequest;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Service public class NotificationWorker{private final JobRepository jobs;private final MedicationPlanRepository plans;private final EmailSender email;private final GoogleCalendarService calendar;private final ObjectMapper mapper;public NotificationWorker(JobRepository jobs,MedicationPlanRepository plans,EmailSender email,GoogleCalendarService calendar,ObjectMapper mapper){this.jobs=jobs;this.plans=plans;this.email=email;this.calendar=calendar;this.mapper=mapper;}
 @Scheduled(fixedDelayString="${notifications.worker-delay-ms:10000}")@Transactional public void jobs(){for(NotificationJob j:jobs.findByStatusInAndNextAttemptAtLessThanEqualOrderByNextAttemptAt(List.of(NotificationJob.Status.PENDING,NotificationJob.Status.RETRY),Instant.now(),PageRequest.of(0,25)))try{EventRequest event=mapper.readValue(j.getPayload(),EventRequest.class);if(j.getChannel()==NotificationJob.Channel.EMAIL)email.send(j.getDestination(),event);else calendar.process(j.getAction(),j.getUserId(),j.getAppointmentId(),event);j.sent();}catch(Exception e){j.failed(e.getMessage());}}
 @Scheduled(fixedDelayString="${notifications.medication-delay-ms:30000}")@Transactional public void medications(){for(MedicationPlan p:plans.due(Instant.now(),PageRequest.of(0,50)))try{String key=p.getDedupeKey()+":"+p.getNextDueAt();if(!jobs.existsByDedupeKey(key)){email.medication(p.getEmail(),p.getMedication(),p.getInstructions());NotificationJob sent=new NotificationJob(key,NotificationJob.Channel.EMAIL,"MEDICATION_REMINDER",p.getUserId(),p.getEmail(),p.getAppointmentId(),"{}");sent.sent();jobs.save(sent);}p.advance();}catch(Exception ignored){}}
}
